def longest_word(words):
    if not words:
        return None
    return max(words, key=len)

def rotate_items(items, k):
    if not items:
        return None
    k %= len(items)
    return tuple(items[-k:] + items[:-k]) if k else tuple(items)

def interleave(left, right):
    if len(left) != len(right):
        raise ValueError("left and right must be equally sized")
    if len(left) == 0:
        return None

    result = []
    for left_item, right_item in zip(left, right):
        result.extend((left_item, right_item))
    return tuple(result)

def sort_labels(labels):
    values = list(labels)
    if not values:
        return None

    distinct = {}
    for label in values:
        key = label.casefold()
        if key not in distinct:
            distinct[key] = label

    return tuple(sorted(distinct.values(), key=str.casefold))

def find_products(products, query):
    if not products:
        return None

    normalized_query = query.casefold()
    return tuple(
        sorted(
            (
                product
                for product in products
                if normalized_query in product["name"].casefold()
            ),
            key=lambda product: product["score"],
            reverse=True,
        )
    )

def group_words(words):
    groups = {}
    for word in words:
        key = word[0].casefold()
        groups.setdefault(key, []).append(word)
    if not groups:
        return None
    return tuple((key, tuple(group)) for key, group in groups.items())

def parse_integer_fields(fields):
    if not fields:
        return None
    return tuple(int(field) for field in fields)

def median_value(values):
    if not values:
        return None
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    if not ranges:
        return None

    sorted_ranges = sorted(ranges, key=lambda r: r[0])
    merged = []
    start, end = sorted_ranges[0]

    for current_start, current_end in sorted_ranges[1:]:
        if current_start <= end:
            end = max(end, current_end)
        else:
            merged.append((start, end))
            start, end = current_start, current_end

    merged.append((start, end))
    return merged

def shortest_path(graph, start, goal):
    if not graph:
        return None
    if start not in graph or goal not in graph:
        raise ValueError("start and goal must be nodes in the graph")
    if start == goal:
        return (start,)

    from collections import deque

    queue = deque([start])
    parent = {start: None}

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor in parent:
                continue
            parent[neighbor] = node
            if neighbor == goal:
                path = []
                current = goal
                while current is not None:
                    path.append(current)
                    current = parent[current]
                return tuple(reversed(path))
            queue.append(neighbor)

    return None

def topological_order(nodes, edges):
    node_order = []
    node_index = {}

    for node in nodes:
        if node not in node_index:
            node_index[node] = len(node_order)
            node_order.append(node)

    if not node_order:
        return None

    adjacency = [[] for _ in node_order]
    indegree = [0] * len(node_order)

    for source, destination in edges:
        source_index = node_index[source]
        destination_index = node_index[destination]
        adjacency[source_index].append(destination_index)
        indegree[destination_index] += 1

    import heapq

    ready = [i for i, degree in enumerate(indegree) if degree == 0]
    heapq.heapify(ready)
    result = []

    while ready:
        current = heapq.heappop(ready)
        result.append(node_order[current])

        for destination in adjacency[current]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                heapq.heappush(ready, destination)

    if len(result) != len(node_order):
        raise ValueError("graph contains a cycle")

    return tuple(result)
